"""Complete 28 original neurological-examination questions."""
from create_exam_neuro_motor_sensory import rows,q,NE,RE,UT,ref
from qbank_authoring import finalize
PU=ref('Stanford Medicine 25: pupillary responses','https://stanfordmedicine25.stanford.edu/the25/pupillary.html')
GR=ref('SAEM GRACE-3 acute dizziness guideline','https://www.saem.org/publications/grace/grace-3')

q('During the swinging-light test, both pupils dilate relatively when light is moved from the right eye to the left. Efferent responses are intact. Which localization is favored?', 'Reduced afferent input from the left retina or optic nerve',[
 ('A left oculomotor parasympathetic defect as the sole mechanism','An efferent defect affects the response of that pupil regardless of which eye is illuminated.'),('A right optic-nerve afferent defect','The relative input loss is on the side receiving the light when both responses weaken.'),('An isolated left sympathetic defect','This causes a different pupillary pattern.')],
 'Compare the input from each eye while observing both pupils','**RAPD reflects asymmetric afferent function.**',['Severe retinal disease or optic neuropathy can cause it.','Symmetric bilateral disease may not produce a relative defect.'],'**Assess acuity, color, fields and fundus.**',['Do not infer an efferent palsy merely from relative dilation during the swing.','Investigate the cause with ophthalmic/neurological assessment.'],[['Left illumination','Weaker bilateral constriction'],['Localization','Left afferent pathway'],['Limit','Relative test misses symmetric loss']],[PU],style='clinical_scenario')

q('A patient develops acute painful ptosis, a down-and-out eye and a dilated poorly reactive pupil. Which action is most appropriate?', 'Urgent assessment for a compressive third-nerve lesion including aneurysm',[
 ('Reassure that pain always proves benign microvascular palsy','Pain does not safely exclude compression.'),('Wait several weeks because all isolated ocular palsies recover','The acute pupil-involving pattern needs urgent evaluation.'),('Diagnose Horner syndrome','Horner produces miosis and usually mild ptosis, not this ophthalmoplegic pattern.')],
 'Pupil involvement can signal a time-sensitive lesion','**The third nerve carries ocular motor and parasympathetic fibers.**',['Aneurysm is an important cause to exclude.','Pupil-sparing patterns also require appropriate modern assessment rather than an absolute benign rule.'],'**Arrange urgent specialist and vascular evaluation.**',['Assess headache and other neurological signs.','Do not let diabetes history alone create reassurance.'],[['Motor','Ptosis/down-and-out'],['Pupil','Dilated/poorly reactive'],['Concern','Compressive CN III lesion']],[PU,NE],style='clinical_scenario')

q('Mild unilateral ptosis with a smaller pupil and anisocoria greater in darkness suggests which syndrome?', 'Horner syndrome',[
 ('A parasympathetic third-nerve palsy','This more often causes a larger poorly reactive pupil with ocular motor deficits.'),('A relative afferent pupillary defect alone','RAPD concerns the light input comparison rather than this resting anisocoria pattern.'),('A fixed bilateral pharmacological mydriasis','This is a different pupil finding.')],
 'Darkness tests the ability to dilate','**Sympathetic dysfunction can produce miosis and dilation lag.**',['Anhidrosis depends on lesion location.','Painful acute Horner can indicate carotid dissection.'],'**Localize and investigate according to onset and associated findings.**',['Assess neck/head pain and other neurological features urgently when present.','Do not call every small pupil pathological without comparison.'],[['Darkness','Anisocoria increases'],['Lid','Mild ptosis'],['Pathway','Sympathetic']],[PU],style='clinical_scenario')

q('On right gaze, the left eye fails to adduct and the right eye has abducting nystagmus. Which lesion is suggested?', 'Left medial longitudinal fasciculus dysfunction causing internuclear ophthalmoplegia',[
 ('Right abducens palsy','That would impair right-eye abduction.'),('Left optic-nerve disease','That affects vision/afferent function rather than this conjugate-gaze pathway.'),('A complete left third-nerve palsy as established by adduction weakness alone','A full third-nerve palsy usually has additional findings; the pattern points to INO.')],
 'Compare the paired movements during horizontal gaze','**The MLF links gaze circuitry to the contralateral medial rectus system.**',['Convergence may be preserved but is not an infallible requirement.','Age and onset guide vascular versus demyelinating and other causes.'],'**Assess the rest of the brainstem examination.**',['Look for associated skew or other deficits.','Use appropriate imaging and cause evaluation.'],[['Failed adduction','Left eye'],['Abducting nystagmus','Right eye'],['Localization','Left MLF']],[NE],style='clinical_scenario')

q('Confrontation testing shows loss of the left visual hemifield in both eyes. Which broad localization is appropriate?', 'Right retrochiasmal visual pathway',[
 ('Left optic nerve alone','A prechiasmal lesion generally affects one eye rather than the same hemifield of both.'),('Central optic chiasm as the typical pattern','This classically produces a bitemporal rather than homonymous defect.'),('Bilateral isolated lens opacity','This does not produce the described homonymous pattern.')],
 'Map the field, not merely the eye reporting poor vision','**Homonymous loss localizes behind the chiasm on the opposite side.**',['Optic tract, radiations or cortex can be involved.','Congruity and other signs can refine localization but are not absolute rules.'],'**Assess onset and neurological urgency.**',['Formal perimetry may define subtle defects.','Do not assume confrontation testing excludes every visual-field abnormality.'],[['Defect','Left homonymous'],['Side','Right'],['Pathway','Retrochiasmal']],[NE])

q('A patient has right lower-facial weakness with relative forehead preservation and right-arm pyramidal weakness. Which localization is favored?', 'A left supranuclear lesion affecting corticobulbar and corticospinal pathways',[
 ('An isolated right peripheral facial-nerve lesion','That more often affects the whole ipsilateral face and does not explain arm pyramidal signs.'),('An isolated neuromuscular-junction disorder','The unilateral combined central pattern is less compatible.'),('A right cerebellar lesion alone','This does not explain the corticobulbar/pyramidal pattern.')],
 'Associated limb signs help interpret facial weakness','**Upper-face input is relatively bilateral, so supranuclear lesions often spare it partly.**',['The pattern is not an absolute rule in every lesion.','A peripheral facial palsy has a different associated examination.'],'**Use the complete acute-neurological assessment.**',['Assess speech, fields and sensation.','Do not diagnose from forehead movement alone.'],[['Face','Contralateral lower-face emphasis'],['Limb','Pyramidal weakness'],['Localization','Opposite supranuclear pathway']],[NE],style='clinical_scenario')

q('A patient has impaired naming and comprehension with paraphasic errors, beyond any articulation problem. Which deficit is most directly demonstrated?', 'Aphasia',[
 ('Dysarthria alone','Dysarthria is impaired motor speech production with language relatively preserved.'),('Dysphonia alone','This concerns voice quality rather than language processing.'),('An isolated cerebellar coordination deficit','That can affect speech rhythm but does not itself explain naming/comprehension loss.')],
 'Language and articulation require separate testing','**Aphasia affects symbolic language functions.**',['Assess fluency, comprehension, naming and repetition.','Hearing, attention and education can confound performance.'],'**Localize with the rest of the cortical examination.**',['Acute onset requires urgent assessment.','Use appropriate communication support rather than assuming poor understanding equals low intelligence.'],[['Aphasia','Language'],['Dysarthria','Articulation'],['Dysphonia','Voice']],[NE],style='clinical_scenario')

q('A patient ignores the left side during grooming and misses left-sided stimuli during simultaneous bilateral testing, despite detecting them alone. Which finding is suggested?', 'Left hemispatial neglect/extinction from a right attention-network lesion',[
 ('A pure left-eye visual loss','Neglect can affect multiple modalities and is not confined to one eye.'),('A homonymous field defect as the only possible mechanism','Extinction and behavioral inattention indicate an attention-network problem, though field loss can coexist.'),('A left peripheral sensory-nerve lesion','That does not explain the broad spatial behavior.')],
 'Attention determines whether a detected signal reaches behavior','**Neglect is distinct from a primary sensory deficit.**',['Right hemispheric networks commonly contribute to left-sided neglect.','Use visual, tactile and functional observations.'],'**Assess safety and rehabilitation needs.**',['Check for coexisting visual-field or sensory loss.','Document the effect on mobility, self-care and awareness.'],[['Single stimulus','May be detected'],['Bilateral competition','Extinction'],['Function','Spatial inattention']],[NE],style='clinical_scenario')

q('A patient lifts the knee excessively and slaps the forefoot down because ankle dorsiflexion is weak. Which gait pattern is described?', 'Steppage gait from foot drop',[
 ('Parkinsonian shuffling','This has a different reduced-stride/postural pattern.'),('A pure cerebellar broad-based gait','That does not specifically explain dorsiflexor weakness.'),('Trendelenburg gait','This relates to hip-abductor weakness rather than foot clearance.')],
 'A gait adaptation can identify a weak movement','**Extra hip/knee flexion compensates for a plantar-flexed foot during swing.**',['Peroneal nerve, root, neuropathic and other causes are possible.','Unilateral versus bilateral distribution refines the differential.'],'**Test dorsiflexion and related muscles to localize further.**',['Assess inversion, eversion, reflexes and sensation.','Provide fall and foot-clearance support as indicated.'],[['Deficit','Dorsiflexion'],['Compensation','High stepping'],['Localization','Requires muscle/sensory mapping']],[NE],style='clinical_scenario')

q('During single-leg stance on the right, the left pelvis drops. Which muscle-function deficit is suggested?', 'Right hip-abductor weakness',[
 ('Left ankle dorsiflexor weakness','This does not maintain the pelvis during right stance.'),('Left hip-adductor weakness as the principal stance stabilizer','The stance-side abductors are the key mechanism tested.'),('Right quadriceps weakness as the only explanation','Knee extension differs from pelvic lateral stabilization.')],
 'The stance limb supports the opposite side of the pelvis','**Gluteal abductors stabilize the pelvis during single-leg support.**',['Pain, joint disease and neurological weakness can affect the test.','A compensatory trunk lean can reduce the load.'],'**Assess hip, nerve and muscle causes.**',['Do not diagnose one nerve lesion from the gait sign alone.','Provide support to prevent a fall during testing.'],[['Stance','Right leg'],['Drop','Left pelvis'],['Weak function','Right hip abductors']],[NE])

q('Ptosis and diplopia worsen with sustained use; pupils, sensation and tendon reflexes are normal. Which localization is favored?', 'Neuromuscular junction',[
 ('A sensory polyneuropathy','This usually produces sensory/reflex abnormalities and does not explain the ocular fatigability pattern.'),('A dorsal-column spinal lesion','This does not explain isolated fluctuating ocular weakness.'),('A fixed unilateral complete third-nerve lesion as the best explanation','Fluctuation and the broader fatigable pattern suggest a different mechanism.')],
 'Fatigability is different from fixed weakness','**Myasthenic disorders can produce use-dependent weakness without sensory loss.**',['Pupil sparing supports the pattern but does not alone establish a diagnosis.','Assess bulbar and respiratory function.'],'**Confirm the suspected junctional disorder with appropriate testing.**',['Antibodies and electrodiagnostics answer complementary questions.','Escalate urgently if swallowing or breathing deteriorates.'],[['Motor','Fluctuating/fatigable'],['Sensation','Usually preserved'],['Pupils','Usually preserved in MG']],[NE],style='clinical_scenario')

q('Acute symmetrical ascending weakness is accompanied by reduced reflexes and paresthesia. Which localization is most consistent?', 'Peripheral nerve/root disease such as a polyradiculoneuropathy',[
 ('A pure muscle disorder as uniquely established','Sensory symptoms and areflexia favor nerve/root involvement.'),('A classic established UMN syndrome','The reflex pattern is different, though acute central mimics must be considered.'),('An isolated neuromuscular-junction disorder','Sensory symptoms are less typical.')],
 'Reflexes and sensation refine the weak-limb syndrome','**Areflexia with progressive weakness can signal an acute polyradiculoneuropathy.**',['A cord lesion, metabolic problem or other mimic can alter the differential.','The examination does not establish GBS subtype by itself.'],'**Assess respiratory, bulbar and autonomic function urgently.**',['Use CSF/electrodiagnostics in the appropriate timing/context.','Do not wait for every confirmatory test if the clinical risk is escalating.'],[['Motor','Progressive symmetric weakness'],['Reflexes','Reduced'],['Support','Peripheral nerve/root localization']],[NE],style='clinical_scenario')

q('A febrile patient with headache and altered mental state has no definite Kernig or Brudzinski sign. Which conclusion is appropriate?', 'Meningitis remains possible; absence of these signs does not safely exclude it',[
 ('Negative meningeal maneuvers exclude all CNS infection','Sensitivity is limited.'),('A normal neck examination proves a primary psychiatric cause','Medical causes remain important.'),('Treatment should wait until every classic sign appears','Time-sensitive infection care should not be delayed for a complete textbook pattern.')],
 'Classic signs have important sensitivity limits','**Host factors and disease stage affect the examination.**',['Older and immunocompromised patients may be atypical.','Assess rash, focal deficits, seizures and systemic instability.'],'**Use the appropriate urgent infection pathway.**',['Plan lumbar puncture/imaging and antimicrobials according to the clinical indication.','Do not use one negative maneuver as a rule-out test.'],[['Signs absent','Disease still possible'],['Context','Fever/headache/altered state'],['Action','Urgent integrated assessment']],[ref('NICE bacterial meningitis and meningococcal disease guideline','https://www.nice.org.uk/guidance/ng240/chapter/Recommendations')],style='clinical_scenario')

q('In which setting is HINTS an appropriate trained-clinician bedside assessment?', 'An acute vestibular syndrome with continuous symptoms and nystagmus, interpreted by a clinician trained in the technique',[
 ('Every brief position-triggered dizzy spell regardless of current findings','Triggered episodic syndromes require a different assessment such as appropriate positional testing.'),('Any fainting episode without nystagmus','This is not the validated HINTS clinical context.'),('An untrained self-test used to exclude stroke','Expertise and correct syndrome selection are essential.')],
 'A powerful test can mislead outside its intended population','**HINTS combines head impulse, nystagmus and skew assessment.**',['Its performance depends strongly on examiner training.','Central or equivocal findings require appropriate further evaluation.'],'**Classify timing/triggers before selecting the examination.**',['Assess gait and associated neurological signs.','Do not let inappropriate HINTS use delay stroke care.'],[['Population','Continuous acute vestibular syndrome'],['Requirement','Nystagmus and trained examiner'],['Not universal','Brief positional dizziness/syncope']],[GR])

if __name__=='__main__':finalize('Clinical Examination',5,'Neurological Examination','exam-neurological',rows,28)
